```ts
interface Symbol
{
    kind: "namespace"|"class"|"interface"|"enum";
    basename: string;
}

interface SymbolClass extends Symbol
{
    kind: "class";
    extends: string;
}

function (symbol: Symbol)
{
    if (symbol.kind === "class")
    {
        //infer symbol as SymbolClass, is it possible?
        console.log(symbol.extends);
    }
